css:
.atelier1864-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2e2a24;
    background: linear-gradient(160deg, #faf5ec 0%, #f3ece0 60%, #efe6d6 100%);
    border-radius: 18px;
}

.atelier1864-container * {
    box-sizing: border-box;
}

.atelier1864-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0f5a55 0%, #14706a 55%, #1d8278 100%);
    color: #f6fbf8;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #0c4a46;
    box-shadow: 0 12px 30px rgba(15, 90, 85, 0.28);
}

.atelier1864-header h1 {
    margin: 10px 0 12px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.atelier1864-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd591;
    background: rgba(255, 213, 145, 0.14);
    border: 1px solid rgba(255, 213, 145, 0.38);
    padding: 5px 14px;
    border-radius: 999px;
}

.atelier1864-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.58;
    color: #e3f3ef;
}

.atelier1864-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6a6052;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.atelier1864-period-counter #currentDay,
.atelier1864-period-counter #maxPeriods {
    font-weight: 800;
    color: #14706a;
}

.atelier1864-round-name {
    background: rgba(20, 112, 106, 0.12);
    color: #0f5a55;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.atelier1864-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b9651a;
    background: rgba(216, 122, 35, 0.12);
    border: 1px solid rgba(216, 122, 35, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.atelier1864-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.atelier1864-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e7dcc8;
    box-shadow: 0 6px 16px rgba(70, 55, 30, 0.08);
    border-top: 4px solid #14706a;
}

.atelier1864-card-transfer { border-top-color: #14706a; }
.atelier1864-card-skill { border-top-color: #2f7fb3; }
.atelier1864-card-completion { border-top-color: #7a5cc0; }
.atelier1864-card-cost { border-top-color: #d87a23; }

.atelier1864-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a8070;
}

.atelier1864-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2e2a24;
    font-variant-numeric: tabular-nums;
}

.atelier1864-card-skill .atelier1864-value { color: #2f7fb3; }
.atelier1864-card-completion .atelier1864-value { color: #7a5cc0; }
.atelier1864-card-cost .atelier1864-value { color: #d87a23; }

/* Transfer-to-Job is the hero KPI — biggest, most colour-coded. */
.atelier1864-card-transfer {
    background: linear-gradient(160deg, #ffffff 0%, #effaf7 100%);
}
.atelier1864-card-transfer .atelier1864-value {
    font-size: 3rem;
    color: #0f5a55;
}

.atelier1864-transfer-strong { border-top-color: #1aa179; }
.atelier1864-transfer-strong .atelier1864-value { color: #1aa179; }
.atelier1864-transfer-weak { border-top-color: #c0392b; }
.atelier1864-transfer-weak .atelier1864-value { color: #c0392b; }

.atelier1864-cost-over { border-top-color: #c0392b; }
.atelier1864-cost-over .atelier1864-value { color: #c0392b; }
.atelier1864-cost-ok { border-top-color: #1aa179; }

.atelier1864-sublabel {
    font-size: 0.76rem;
    color: #968a76;
    line-height: 1.35;
}

.atelier1864-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fff7ea;
    border: 1px solid #ecd9b8;
    color: #5c4d36;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.atelier1864-budget-bar #budgetDisplay {
    font-size: 1.08rem;
    letter-spacing: 0.3px;
    color: #b9651a;
}

.atelier1864-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #d87a23;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(70, 55, 30, 0.08);
}

.atelier1864-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.atelier1864-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #0f5a55;
    margin-bottom: 6px;
}

.atelier1864-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #4a4338;
}

.atelier1864-briefing-text strong { color: #0f5a55; }
.atelier1864-briefing-text em { color: #b9651a; font-style: italic; }

.atelier1864-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e7dcc8;
    box-shadow: 0 6px 16px rgba(70, 55, 30, 0.08);
}

.atelier1864-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2e2a24;
    border-bottom: 2px solid #efe6d6;
    padding-bottom: 8px;
}

.atelier1864-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3c352b;
    margin: 14px 0 6px;
}

.atelier1864-container select,
.atelier1864-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8ccb4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdfaf3;
    color: #2e2a24;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.atelier1864-container select:focus,
.atelier1864-container input[type="number"]:focus {
    outline: none;
    border-color: #14706a;
    box-shadow: 0 0 0 3px rgba(20, 112, 106, 0.16);
}

.atelier1864-container select option {
    background-color: #fdfaf3;
    color: #2e2a24;
}

.atelier1864-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #d87a23;
}

.atelier1864-range-readout,
.atelier1864-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6a6052;
    margin-top: 4px;
}

.atelier1864-range-readout span:nth-child(2),
.atelier1864-alloc-readout span:nth-child(2) {
    color: #b9651a;
    font-weight: 800;
}

.atelier1864-hint {
    font-size: 0.8rem;
    color: #968a76;
    margin-top: 6px;
    line-height: 1.45;
    background: #fbf6ec;
    border: 1px dashed #e2d4ba;
    border-radius: 8px;
    padding: 8px 10px;
}

.atelier1864-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.atelier1864-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #fbf6ec;
    border: 1px solid #e6d8bf;
    border-radius: 9px;
    padding: 8px 12px;
}

.atelier1864-alloc-name {
    flex: 1;
    font-size: 0.86rem;
    font-weight: 600;
    color: #4a4338;
}

.atelier1864-alloc-row input[type="number"] {
    width: 110px;
    flex: 0 0 110px;
}

.atelier1864-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.atelier1864-container .btn-primary {
    background: linear-gradient(135deg, #0f5a55 0%, #1d8278 100%);
    border: none;
    color: #f6fbf8;
    padding: 11px 28px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(15, 90, 85, 0.32);
}

.atelier1864-container .btn-primary:hover {
    filter: brightness(1.08);
}

.atelier1864-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8ccb4;
    color: #6a6052;
    background: transparent;
}

.atelier1864-coach {
    background: linear-gradient(160deg, #103f3b 0%, #0f5a55 100%);
    color: #e6f4f0;
    border: 1px solid #0c4a46;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(15, 90, 85, 0.25);
}

.atelier1864-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd591;
    margin-bottom: 8px;
}

.atelier1864-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.atelier1864-coach-body strong { color: #ffd591; }
.atelier1864-coach-body em { color: #9fe6d4; font-style: italic; }

.atelier1864-history,
.atelier1864-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e7dcc8;
    box-shadow: 0 6px 16px rgba(70, 55, 30, 0.08);
}

.atelier1864-history h3,
.atelier1864-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0f5a55;
}

.atelier1864-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a4338;
}

.atelier1864-container table#usfHistoryTable th {
    background: #f3ece0;
    color: #0f5a55;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2d4ba;
}

.atelier1864-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efe6d6;
    color: #4a4338;
}

.atelier1864-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fbf6ec;
}

.atelier1864-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .atelier1864-container {
        padding: 14px;
    }
    .atelier1864-header h1 {
        font-size: 1.7rem;
    }
    .atelier1864-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .atelier1864-value {
        font-size: 2rem;
    }
    .atelier1864-card-transfer .atelier1864-value {
        font-size: 2.3rem;
    }
    .atelier1864-clock {
        margin-left: 0;
    }
    .atelier1864-period-counter {
        font-size: 0.88rem;
    }
    .atelier1864-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .atelier1864-alloc-row {
        flex-wrap: wrap;
    }
    .atelier1864-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .atelier1864-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.atelier1864-cm { background:#faf8f4; color:#211d14; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.atelier1864-cm-head { text-align:center; border-bottom:1px solid #e7e1d5; padding-bottom:14px; margin-bottom:16px; }
.atelier1864-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#6b6252; font-weight:700; }
.atelier1864-cm-scorewrap { margin:8px 0 2px; }
.atelier1864-cm-score { font-size:52px; font-weight:800; color:#b5730b; line-height:1; }
.atelier1864-cm-score-max { font-size:20px; color:#948a78; font-weight:600; }
.atelier1864-cm-grade { font-size:19px; font-weight:700; color:#211d14; margin-top:4px; }
.atelier1864-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.atelier1864-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.atelier1864-cm-met { background:#e6eed6; color:#5a6b18; }
.atelier1864-cm-fail { background:#fce0dc; color:#a4322a; }
.atelier1864-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.atelier1864-cm-metric { background:#f0ece3; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.atelier1864-cm-metric-val { font-size:22px; font-weight:800; color:#211d14; }
.atelier1864-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#6b6252; margin-top:3px; }
.atelier1864-cm-insights { background:#f0ece3; border-radius:10px; padding:14px 18px; }
.atelier1864-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#6b6252; font-weight:700; margin-bottom:8px; }
.atelier1864-cm-insights ul { margin:0; padding-left:18px; }
.atelier1864-cm-insights li { font-size:14px; line-height:1.5; color:#332d20; margin-bottom:7px; }

