(function() {
    'use strict';

    class AtelierAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Build the Program`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Atelier Apprend / Nordpharm), all EUR.
            this.LEARNERS = 240;            // first cohort
            this.CEILING = 4500;            // EUR per-learner budget ceiling, no contingency
            this.BASELINE_TRANSFER = 22;    // % measured transfer across last 12 programs
            this.AI_DIAGNOSTIC_COST = 320;  // EUR/learner mid-round reveal
            this.SUCCESS_TARGET = 45;       // a credible doubling teams should aim for

            // Concept truths — the design choices the math rewards.
            this.TRUE_CHALLENGE = `behavior`;
            this.TRUE_METRIC = `businessmetric`;
            this.TRUE_AI = `enhance`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    transfer: this.BASELINE_TRANSFER, // % transfer-to-job (hero KPI)
                    skill: 30,                         // capability lift on the scoped challenge (0–100)
                    completion: 60,                    // % of cohort finishing
                    cost: 0,                           // EUR per-learner cost build-up
                    scoped: false,                     // did R1 land one measurable behavior
                    overBudget: false,                 // breached the €4,500 ceiling
                    aiBlocked: false,                  // works council blocked the diagnostic
                    overPromised: false,               // promised an indefensible transfer target
                    transferHistory: [this.BASELINE_TRANSFER],
                    skillHistory: [30],
                    completionHistory: [60],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the COMMON ERRORS — a click-through must not auto-win.
                state.decisions = {
                    challenge: `vague`,
                    metric: `satisfaction`,
                    scope: 40,
                    action: 1500,
                    sponsor: 500,
                    intensive: 800,
                    digital: 700,
                    completionDriver: `hours`,
                    ai: `diagnostic`,
                    consent: `none`,
                    fallback: `none`,
                    measure: `happysheet`,
                    target: `safe`,
                    case: `polish`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ch = document.getElementById(`challengeInput`);
                const me = document.getElementById(`metricInput`);
                const sc = document.getElementById(`scopeInput`);
                if (ch) decisions.challenge = ch.value;
                if (me) decisions.metric = me.value;
                if (sc) decisions.scope = parseInt(sc.value, 10);
                if (!Number.isFinite(decisions.scope) || decisions.scope < 0 || decisions.scope > 100) {
                    warn(`warn_scope_range`); return false;
                }
            } else if (round === 2) {
                const ac = document.getElementById(`actionInput`);
                const sp = document.getElementById(`sponsorInput`);
                const it = document.getElementById(`intensiveInput`);
                const di = document.getElementById(`digitalInput`);
                const cd = document.getElementById(`completionInput`);
                if (ac) decisions.action = parseFloat(ac.value);
                if (sp) decisions.sponsor = parseFloat(sp.value);
                if (it) decisions.intensive = parseFloat(it.value);
                if (di) decisions.digital = parseFloat(di.value);
                if (cd) decisions.completionDriver = cd.value;
                const parts = [decisions.action, decisions.sponsor, decisions.intensive, decisions.digital];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = decisions.action + decisions.sponsor + decisions.intensive + decisions.digital;
                if (total <= 0) {
                    warn(`warn_alloc_zero`); return false;
                }
                // The ceiling is hard but learners are allowed to breach it — that IS the gold-plating error,
                // penalised in calculateResults rather than blocked here.
            } else if (round === 3) {
                const ai = document.getElementById(`aiInput`);
                const co = document.getElementById(`consentInput`);
                const fb = document.getElementById(`fallbackInput`);
                if (ai) decisions.ai = ai.value;
                if (co) decisions.consent = co.value;
                if (fb) decisions.fallback = fb.value;
                if (!decisions.ai) { warn(`warn_ai_choice`); return false; }
            } else if (round === 4) {
                const me = document.getElementById(`measureInput`);
                const tg = document.getElementById(`targetInput`);
                const ca = document.getElementById(`caseInput`);
                const cv = document.getElementById(`convictionInput`);
                if (me) decisions.measure = me.value;
                if (tg) decisions.target = tg.value;
                if (ca) decisions.case = ca.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let transferDelta = 0, skillDelta = 0, completionDelta = 0, costDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // SCOPE THE REAL CHALLENGE — scope precedes design (Common Error 1: fuzzy brief).
                switch (d.challenge) {
                    case `behavior`:
                        ds.scoped = true;
                        transferDelta += 7; skillDelta += 8; coachKey = `coach_r1_sharp`; break;
                    case `decisions`:
                        // Plausible but not tied to a metric — partial credit.
                        transferDelta += 2; skillDelta += 3; coachKey = `coach_r1_partial`; break;
                    case `vague`:
                        transferDelta -= 4; skillDelta += 2; coachKey = `coach_r1_vague`; break;
                    case `all`:
                        // Trying to attack three problems dilutes everything.
                        transferDelta -= 6; skillDelta -= 2; completionDelta -= 4; coachKey = `coach_r1_all`; break;
                }

                // Define the success metric (Common Error 5: measuring only reaction).
                switch (d.metric) {
                    case `businessmetric`:
                        transferDelta += 6; skillDelta += 4;
                        if (d.challenge === `behavior`) coachKey = `coach_r1_metricbiz`; break;
                    case `knowledge`:
                        skillDelta += 4; transferDelta -= 1; break;
                    case `satisfaction`:
                        completionDelta += 2; transferDelta -= 5; coachKey = `coach_r1_metricsat`; break;
                }

                // Out-of-scope discipline — focus buys transfer.
                if (d.scope >= 60) { transferDelta += 4; skillDelta += 4; }
                else if (d.scope <= 25) { transferDelta -= 4; coachKey = `coach_r1_noscope`; }

                summaryKey = (d.challenge === `behavior` && d.metric === `businessmetric`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // SELECT THE FORMAT against the €4,500 ceiling (Common Errors 2 & 3).
                const total = d.action + d.sponsor + d.intensive + d.digital;
                ds.cost = Math.round(total);

                // Transfer is driven mainly by the action-learning core + accountable sponsors.
                // Digital alone is scalable but historically weak; intensives add impact but cost-heavy.
                const actionShare = total > 0 ? d.action / total : 0;
                const sponsorShare = total > 0 ? d.sponsor / total : 0;
                const digitalShare = total > 0 ? d.digital / total : 0;

                // The action-learning core + accountable sponsors drive transfer; digital actively
                // erodes it (the historical 22% was a digital cohort). Net effect is intentionally
                // small for a balanced blend and negative for a digital-dominated one.
                transferDelta += actionShare * 18 + sponsorShare * 11 - digitalShare * 22;
                skillDelta += actionShare * 12 + (d.intensive / total) * 11 + digitalShare * 5;
                // Digital scales completion; pure high-touch can fatigue without a completion engine.
                completionDelta += digitalShare * 14 + sponsorShare * 8 + (d.intensive / total) * 4 - actionShare * 2;

                // Budget discipline (Common Error 3: gold-plating).
                if (total > this.CEILING) {
                    ds.overBudget = true;
                    const over = total - this.CEILING;
                    // Every €100 over the ceiling costs credibility AND transfer (Nordpharm won't pay it).
                    transferDelta -= Math.min(20, over / 100 * 1.5);
                    completionDelta -= Math.min(10, over / 100 * 0.6);
                    coachKey = `coach_r2_goldplate`;
                } else if (d.digital >= total * 0.55 && d.action <= total * 0.25) {
                    // Cheap, digital-heavy design (Common Error 2: cost over impact). The savings buy
                    // the exact weak-transfer outcome that loses the framework — a direct transfer hit.
                    transferDelta -= 10;
                    coachKey = `coach_r2_cheap`;
                } else if (d.action >= total * 0.4 && d.sponsor > 0) {
                    coachKey = `coach_r2_balanced`;
                } else {
                    coachKey = `coach_r2_mixed`;
                }

                // Drive completion without padding (Common Error: padding seat-hours).
                switch (d.completionDriver) {
                    case `sponsor`: completionDelta += 12; transferDelta += 5; break;
                    case `grades`: completionDelta += 4; transferDelta -= 2; break;
                    case `hours`: completionDelta += 2; skillDelta -= 2; transferDelta -= 3; coachKey = (coachKey === `coach_default` || coachKey === `coach_r2_mixed`) ? `coach_r2_padding` : coachKey; break;
                }

                // No real action-learning core at all = a generic program; transfer cannot land.
                if (d.action <= total * 0.12) { transferDelta -= 8; if (coachKey !== `coach_r2_goldplate`) coachKey = `coach_r2_nocore`; }

                summaryKey = (!ds.overBudget && d.action >= total * 0.4 && d.completionDriver === `sponsor`) ? `sum_r2_good` :
                             (ds.overBudget ? `sum_r2_over` :
                             (d.digital >= total * 0.55 ? `sum_r2_cheap` : `sum_r2_weak`));
            } else if (round === 3) {
                // EMBED THE AI TOOL (Common Error 4: AI without governance; AI as substitute).
                // Mid-round event: works council files a query; diagnostic adds €320/learner.
                switch (d.ai) {
                    case `enhance`:
                        // AI as enhancer of action-learning — the concept's right answer.
                        transferDelta += 6; skillDelta += 7; completionDelta += 10; coachKey = `coach_r3_enhance`; break;
                    case `diagnostic`:
                        // Powerful but the works-council flashpoint AND it adds €320/learner.
                        costDelta += this.AI_DIAGNOSTIC_COST;
                        skillDelta += 6; completionDelta += 6;
                        if (d.consent === `minimized`) {
                            transferDelta += 6; coachKey = `coach_r3_diaggoverned`;
                        } else {
                            // Switched on profiling without consent — launch freezes.
                            ds.aiBlocked = true;
                            transferDelta -= 12; completionDelta -= 14; skillDelta -= 6;
                            coachKey = `coach_r3_blocked`;
                        }
                        break;
                    case `replace`:
                        // AI as substitute for the action-learning core (Common Error 6).
                        transferDelta -= 10; skillDelta += 2; completionDelta += 8; coachKey = `coach_r3_replace`; break;
                    case `off`:
                        // Safe, but throws away the differentiator the board asked for.
                        completionDelta -= 2; coachKey = `coach_r3_off`; break;
                }

                // Consent / data design — governs whether the AI helps or stalls (GDPR / works council).
                switch (d.consent) {
                    case `minimized`:
                        transferDelta += 4; completionDelta += 4;
                        if (ds.aiBlocked) { ds.aiBlocked = false; } // governed design clears the query
                        break;
                    case `notice`:
                        if (d.ai === `diagnostic` || d.ai === `replace`) { transferDelta -= 4; coachKey = `coach_r3_notice`; }
                        break;
                    case `none`:
                        if (d.ai !== `off`) {
                            transferDelta -= 6; completionDelta -= 6;
                            if (d.ai !== `diagnostic`) coachKey = `coach_r3_noconsent`;
                        }
                        break;
                }

                // Fallback if the diagnostic is blocked — resilience under the works-council injection.
                switch (d.fallback) {
                    case `manual`: transferDelta += 4; completionDelta += 4; if (ds.aiBlocked) { transferDelta += 4; completionDelta += 6; } break;
                    case `pause`: transferDelta -= 4; completionDelta -= 8; coachKey = (coachKey === `coach_default`) ? `coach_r3_pause` : coachKey; break;
                    case `none`: if (ds.aiBlocked) { transferDelta -= 4; completionDelta -= 6; } break;
                }

                summaryKey = (d.ai === `enhance` && d.consent === `minimized`) ? `sum_r3_good` :
                             (ds.aiBlocked ? `sum_r3_blocked` :
                             (d.ai === `replace` ? `sum_r3_replace` : `sum_r3_weak`));
            } else if (round === 4) {
                // PROVE THE IMPACT — measure transfer, not reaction (Common Error 5).
                switch (d.measure) {
                    case `transfer`:
                        transferDelta += 7; skillDelta += 4; coachKey = `coach_r4_measure`; break;
                    case `knowledge`:
                        skillDelta += 4; transferDelta -= 2; break;
                    case `happysheet`:
                        transferDelta -= 8; completionDelta += 2; coachKey = `coach_r4_happy`; break;
                }

                // Target transfer-to-job vs the 22% baseline — must be defensible by the design.
                // A target the design can't evidence is over-promising; a timid one wins nothing.
                const designStrong = ds.scoped && !ds.overBudget && d.measure === `transfer`;
                switch (d.target) {
                    case `credible`:
                        if (designStrong) { transferDelta += 6; coachKey = `coach_r4_credible`; }
                        else { transferDelta += 2; }
                        break;
                    case `moonshot`:
                        ds.overPromised = true;
                        transferDelta -= 6; coachKey = `coach_r4_moonshot`; break;
                    case `safe`:
                        transferDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_safe` : coachKey; break;
                }

                // The renewal case — lead with proof of transfer, not polish or tech.
                switch (d.case) {
                    case `evidence`:
                        transferDelta += 6; skillDelta += 2;
                        if (designStrong) coachKey = `coach_r4_win`; break;
                    case `ai`:
                        transferDelta -= 2; coachKey = `coach_r4_caseai`; break;
                    case `polish`:
                        transferDelta -= 4; coachKey = `coach_r4_casepolish`; break;
                }

                if (d.conviction >= 60) { transferDelta += 4; skillDelta += 2; }
                else if (d.conviction <= 25) { transferDelta -= 4; }

                summaryKey = (d.measure === `transfer` && d.target === `credible` && d.case === `evidence`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas. Transfer is a %, clamp 0–100. Cost accumulates in R2 (set) + R3 (diagnostic add).
            if (round === 3 && costDelta) {
                ds.cost = Math.round(ds.cost + costDelta);
                if (ds.cost > this.CEILING && !ds.overBudget) {
                    // The €320 diagnostic just pushed the design over the ceiling.
                    ds.overBudget = true;
                    transferDelta -= 5; completionDelta -= 4;
                    if (coachKey === `coach_r3_diaggoverned`) coachKey = `coach_r3_diagoverbudget`;
                }
            }

            ds.transfer = Math.max(0, Math.min(100, Math.round(ds.transfer + transferDelta)));
            ds.skill = Math.max(0, Math.min(100, Math.round(ds.skill + skillDelta)));
            ds.completion = Math.max(0, Math.min(100, Math.round(ds.completion + completionDelta)));

            ds.transferHistory.push(ds.transfer);
            ds.skillHistory.push(ds.skill);
            ds.completionHistory.push(ds.completion);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                transfer: ds.transfer,
                transferDelta: Math.round(transferDelta),
                skill: ds.skill,
                skillDelta: Math.round(skillDelta),
                completion: ds.completion,
                completionDelta: Math.round(completionDelta),
                cost: ds.cost,
                overBudget: ds.overBudget,
                aiBlocked: ds.aiBlocked,
                scoped: ds.scoped,
                overPromised: ds.overPromised,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware EUR (whole euros): English "€4,500", Spanish "4.500 €".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) || 0);
            if (lang === `es`) {
                return `${n.toLocaleString(`de-DE`)} €`;
            }
            return `€${n.toLocaleString(`en-US`)}`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`transferDisplay`, `domainState.transfer`, (v) => {
                const card = document.querySelector(`.atelier1864-card-transfer`);
                if (card) {
                    card.classList.toggle(`atelier1864-transfer-strong`, Number(v) >= 45);
                    card.classList.toggle(`atelier1864-transfer-weak`, Number(v) <= 22);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`skillDisplay`, `domainState.skill`, (v) => Math.round(Number(v)));
            uiManager.bind(`completionDisplay`, `domainState.completion`, (v) => Math.round(Number(v)) + `%`);
            uiManager.bind(`costDisplay`, `domainState.cost`, (v) => {
                const card = document.querySelector(`.atelier1864-card-cost`);
                if (card) {
                    card.classList.toggle(`atelier1864-cost-over`, Number(v) > self.CEILING);
                    card.classList.toggle(`atelier1864-cost-ok`, Number(v) > 0 && Number(v) <= self.CEILING);
                }
                return self._fmtMoney(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.cost`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.CEILING);
            });

            // Out-of-scope discipline slider readout.
            const sc = document.getElementById(`scopeInput`);
            const scReadout = document.getElementById(`scopeReadout`);
            if (sc && scReadout) {
                scReadout.textContent = sc.value;
                sc.addEventListener(`input`, function() { scReadout.textContent = sc.value; });
            }

            // Format-blend live total (must stay at or below €4,500).
            const allocIds = [`actionInput`, `sponsorInput`, `intensiveInput`, `digitalInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total.toLocaleString(`en-US`);
                const bar = document.querySelector(`.atelier1864-alloc-readout`);
                if (bar) bar.style.color = (total > self.CEILING) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

