        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.transferHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                atelierChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.transferHistory },
                        { data: ds.skillHistory },
                        { data: ds.completionHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const transfer = Math.round(ds.transfer);
            const skill = Math.round(ds.skill);
            const completion = Math.round(ds.completion);
            const cost = Math.round(ds.cost);
            const costPenalty = cost > this.CEILING ? Math.min(30, (cost - this.CEILING) / 100 * 2) : 0;
            return Math.max(0, Math.round(transfer * 0.46 + skill * 0.22 + completion * 0.22 + 10 - costPenalty));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const transfer = Math.round(ds.transfer);
            const skill = Math.round(ds.skill);
            const completion = Math.round(ds.completion);
            const cost = Math.round(ds.cost);

            // Composite weights transfer-to-job most heavily — it is the renewal metric.
            // A cost overrun is a hard penalty (Nordpharm will not pay over €4,500).
            const composite = this._composite(ds);

            const beatBaseline = transfer > this.BASELINE_TRANSFER + 3;
            const hitTarget = transfer >= this.SUCCESS_TARGET;
            const inBudget = cost <= this.CEILING && cost > 0;
            const renews = hitTarget && inBudget && !ds.aiBlocked;

            let performanceKey = `grade_lost`;
            if (renews && composite >= 75) performanceKey = `grade_renewed`;
            else if (renews) performanceKey = `grade_secured`;
            else if (ds.aiBlocked) performanceKey = `grade_frozen`;
            else if (!inBudget && ds.overBudget) performanceKey = `grade_blown`;
            else if (beatBaseline && composite >= 55) performanceKey = `grade_improved`;
            else if (!beatBaseline) performanceKey = `grade_baseline`;
            const met = renews && composite >= 75;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (renews) insights.push(window.mySimulation.t(`insight_renew`));
            else if (ds.aiBlocked) insights.push(window.mySimulation.t(`insight_blocked`));
            else if (!beatBaseline) insights.push(window.mySimulation.t(`insight_baseline`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!ds.scoped) insights.push(window.mySimulation.t(`insight_fuzzy`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (ds.overPromised) insights.push(window.mySimulation.t(`insight_overpromise`));
            if (transfer >= this.SUCCESS_TARGET && inBudget) insights.push(window.mySimulation.t(`insight_transfer`));

            return {
                transfer: transfer,
                skill: skill,
                completion: completion,
                cost: cost,
                beatBaseline: beatBaseline,
                hitTarget: hitTarget,
                inBudget: inBudget,
                renews: renews,
                aiBlocked: !!ds.aiBlocked,
                overBudget: !!ds.overBudget,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="atelier1864-cm-badge ` + (s.met ? `atelier1864-cm-met` : `atelier1864-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.aiBlocked) badges.push(`<span class="atelier1864-cm-badge atelier1864-cm-fail">` + t(`cm_fail_frozen`) + `</span>`);
            if (s.overBudget) badges.push(`<span class="atelier1864-cm-badge atelier1864-cm-fail">` + t(`cm_fail_budget`) + `</span>`);
            if (s.hitTarget === false) badges.push(`<span class="atelier1864-cm-badge atelier1864-cm-fail">` + t(`cm_fail_target`) + `</span>`);
            const kpi = (label, val) => `<div class="atelier1864-cm-metric"><div class="atelier1864-cm-metric-val">` + val + `</div><div class="atelier1864-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_transfer`), (s.transfer != null ? s.transfer : 0) + `%`) + kpi(t(`cm_skill`), (s.skill != null ? s.skill : 0)) + kpi(t(`cm_completion`), (s.completion != null ? s.completion : 0) + `%`) + kpi(t(`cm_cost`), `€` + (s.cost != null ? s.cost : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="atelier1864-cm">`
                + `<div class="atelier1864-cm-head"><div class="atelier1864-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="atelier1864-cm-scorewrap"><span class="atelier1864-cm-score">` + score + `</span><span class="atelier1864-cm-score-max">/100</span></div>`
                + `<div class="atelier1864-cm-grade">` + grade + `</div>`
                + `<div class="atelier1864-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="atelier1864-cm-metrics">` + kpis + `</div>`
                + `<div class="atelier1864-cm-insights"><div class="atelier1864-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.aiBlocked) return window.mySimulation.t(`hint_blocked`);
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (!ds.scoped && state.currentPeriod >= 2) return window.mySimulation.t(`hint_fuzzy`);
            if (ds.transfer <= this.BASELINE_TRANSFER && state.currentPeriod >= 2) return window.mySimulation.t(`hint_transfer`);
            if (ds.overPromised) return window.mySimulation.t(`hint_overpromise`);
            if (ds.transfer >= this.SUCCESS_TARGET && ds.cost <= this.CEILING && ds.cost > 0) return window.mySimulation.t(`hint_strong`);
            return null;
        }

